package edu.eci.cvds.ECIReserves.service;import edu.eci.cvds.ECIReserves.model.Laboratory;import edu.eci.cvds.ECIReserves.repository.LaboratoryRepository;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import java.time.LocalDateTime;import java.time.ZoneId;import java.util.*;import java.util.function.Consumer;import java.util.function.Predicate;@Servicepublic class LaboratoryService {    private final LaboratoryRepository laboratoryRepository;    private final List<Laboratory> laboratories = new ArrayList<>();    public LaboratoryService(LaboratoryRepository laboratoryRepository) {        this.laboratoryRepository = laboratoryRepository;    }    public ArrayList<Laboratory>  getAvailableLabs(){ return new ArrayList<>();    }    public Laboratory addLab(Laboratory lab) {        if (!isOkLab(lab)) {            return null;        }        laboratories.add(lab);       return laboratoryRepository.save(lab);    }    public Laboratory updateLab(String id, Laboratory updatedLab) {        Laboratory existingLab = laboratoryRepository.findById(id)                .orElseThrow(() -> new NoSuchElementException("Laboratorio no encontrado"));        updateFieldIfValid(updatedLab.getName(), existingLab::setName);        updateFieldIfValid(updatedLab.getComputers(), existingLab::setComputers, val -> val > 0);        updateFieldIfValid(updatedLab.getCapacity(), existingLab::setCapacity, val -> val > 0);        updateFieldIfValid(updatedLab.getOpeningTime(), existingLab::setOpeningTime);        updateFieldIfValid(updatedLab.getClosingTime(), existingLab::setClosingTime);        return laboratoryRepository.save(existingLab);    }    public void deleteLab(String id){        laboratoryRepository.deleteById(id);        Laboratory lab = getLabByID(id);        laboratories.remove(lab);    }    public List<Laboratory> findAvailableLabsBetween(LocalDateTime start, LocalDateTime end) {        Date startDate = convertToDate(start);        Date endDate = convertToDate(end);        return laboratoryRepository.findByOpeningTimeBetween(startDate, endDate);    }    public boolean isLabAvailable(String labId, LocalDateTime start, LocalDateTime end){return false;}    public ArrayList<Laboratory> searchLabs(String name, Integer minCapacity, Integer minComputers, Boolean available){ return new ArrayList<>();}    public List<Laboratory> getLabsByName(String name) {        return laboratoryRepository.findByName(name);    }    public List<Laboratory> getLabsByCapacity(int minCapacity) {        return laboratoryRepository.findByCapacityGreaterThanEqual(minCapacity);    }    public List<Laboratory> getLabsByComputers(int minComputers) {        return laboratoryRepository.findByComputersGreaterThanEqual(minComputers);    }    public List<Laboratory> getLabsByOpeningTime(LocalDateTime openingTime) {        return laboratoryRepository.findByOpeningTime(openingTime);    }    public List<Laboratory> getLabsByClosingTime(LocalDateTime closingTime) {        return laboratoryRepository.findByClosingTime(closingTime);    }    public Laboratory getLabByID(String id) {        for (Laboratory lab : laboratories) {            if (lab.getId().equals(id)) {                return lab;            }        }        return null;    }    private boolean isOkLab(Laboratory lab){        if(lab.getCapacity() <= 0){return false;}        if(lab.getId() == null){return false;}        if(lab.getName() == null){return false;}        if(lab.getDescription() == null){return false;}        if(lab.getComputers() < 0 || lab.getComputers() == null){ return false;}        if(lab.getOpeningTime() == null){return false;}        if(lab.getClosingTime() == null){return false;}        return true;    }    private <T> void updateFieldIfValid(T newValue, Consumer<T> setter) {        if (newValue != null) {            setter.accept(newValue);        }    }    private <T> void updateFieldIfValid(T newValue, Consumer<T> setter, Predicate<T> condition) {        if (newValue != null && condition.test(newValue)) {            setter.accept(newValue);        }    }    private Date convertToDate(LocalDateTime dateToConvert) {        return Date.from(dateToConvert.atZone(ZoneId.systemDefault()).toInstant());    }}